"""Build the lay-facing 05a view from frozen iteration-05 data and geometry."""
from pathlib import Path
import json
import re
from html import escape

ROOT = Path(__file__).resolve().parents[1]
SITE = ROOT / 'site/structural'
DATA = json.loads((SITE / 'iteration-05-data.json').read_text())
MODEL = json.loads((ROOT / 'site/assets/structural-models-05.json').read_text())['variants'][0]
TABS = json.loads((SITE / 'navigation.json').read_text())

def tabs(current):
    return '<nav class="design-tabs" aria-label="Structural design iterations">' + ''.join('<a href="'+url+'"'+(' aria-current="page"' if url == current else '')+'>'+label+'</a>' for url,label in TABS) + '</nav>'

def member_group(name):
    if name.startswith('Deck edge'): return 0
    if name.startswith('Truss lower'): return 1
    if name.startswith('Floor joist'): return 2
    if name.startswith('Truss vertical') and name.rsplit(' ',1)[-1] in ('4','5'): return 3
    if name.startswith(('Truss vertical','Truss web','Lower transverse')): return 4
    if 'corner post' in name: return 5
    if 'transverse sill' in name: return 6
    if name.startswith('Roof bay'): return 7
    if 'portal crossmember' in name: return 8
    if 'portal X brace' in name: return 9
    if 'knee brace' in name: return 10
    raise ValueError(name)

specs = [
 ('Upper side chords / edge girders','6 × 2 in','⅛ in','6 in vertical'),
 ('Lower side chords','6 × 2 in','3/16 in','6 in vertical; thicker wall around the open bay'),
 ('Deck joists','4 × 2 in','⅛ in','4 in vertical; spacing no more than 24 in'),
 ('Access-opening jambs','4 × 2 in','⅛ in','4 in in the side-truss plane; 2 in across the bus'),
 ('Other truss verticals, diagonals and raised ties','2 × 2 in','⅛ in','Square HSS; cross-ties are raised above the modeled roof'),
 ('Front and rear portal corner posts','4 × 4 in','¼ in','Square HSS'),
 ('Front and rear transverse sills','8 × 3 in','¼ in','8 in vertical'),
 ('Roof-plane X braces','45 × 45 mm ≈ 1.77 in square','⅛ in','Inherited modeled size; stock selection unresolved'),
 ('Portal crossmembers','65 × 65 mm ≈ 2.56 in square','3/16 in','Inherited modeled size; stock selection unresolved'),
 ('Portal X braces','38 × 38 mm ≈ 1.50 in square','3/16 in','Inherited modeled size; stock selection unresolved'),
 ('Portal and side knee braces','≈52 × 52 mm ≈ 2.05 in square','3/16 in','Inherited modeled size; stock selection unresolved'),
]
schedule=[]
for i,(name,size,wall,note) in enumerate(specs):
    members=[m for m in MODEL['members'] if member_group(m['name'])==i]
    assert members
    schedule.append(dict(group=name,size=size,nominalWall=wall,note=note,members=[dict(name=m['name'],widthM=m['width'],depthM=m['depth'],nominalWallM=m.get('wall',.93*.003175)/.93) for m in members]))
material_data=dict(revision='05a',basis='ASTM A500 Grade C carbon-steel HSS; explicit provisional specification consistent with the existing assumed 345 MPa yield strength',yieldMPa=345,elasticModulusGPa=200,densityKgM3=7850,designWallFactor=.93,procurementApproved=False,stockAvailabilityVerified=False,groups=schedule)
(SITE/'iteration-05a-materials.json').write_text(json.dumps(material_data,indent=2)+'\n')
schedule_rows=''.join('<tr><th scope="row">'+escape(r['group'])+'</th><td>'+escape(r['size'])+'</td><td><strong>'+r['nominalWall']+'</strong></td><td>'+escape(r['note'])+'</td></tr>' for r in schedule)

cards=[]
for i,(tag,title,weight,tradeoff,note) in enumerate([
 ('Iteration 04','Shallow grid + shores',3524,'Lightest of these three. It needs six load paths through Earl’s body.','Body-path stiffness assumed: 5,000 lbf/in per shore.'),
 ('Earlier 05 trial','Light truss + shores',4080,'Smaller calculated drop here, but still depends on six body shores.','No dedicated access bay in this earlier truss.'),
 ('Current 05 candidate','Accessible perimeter truss',4493,'Permanent access openings and zero body-support credit. About 969 lb heavier than 04.','Preferred for the cabin/access brief; end mounts remain unverified.'),
]):
    row=([r for r in DATA['comparisons'] if r['concept']==['grid04','light-truss'][i] and r['people']==20 and r['share']==1][0] if i<2 else next(r for r in DATA['equipment'] if r['people']==20 and r['extraLbf']==0))
    pct=round(row['stress']/207*100)
    cards.append(f'''<article class="comparison-card yellow" id="comparison-{i}"><div class="card-main"><span class="concept-tag">{tag}</span><h3>{title}</h3><div class="percent-number" id="comparison-use-{i}">{pct}%</div><p class="result-label">of the chosen stress limit</p><p id="comparison-status-{i}">Near the chosen limit</p><div class="meter" aria-hidden="true"><span id="comparison-bar-{i}"></span></div><p class="weight">{weight:,} lb</p><p class="card-note">frame + floor + supports</p></div><div class="card-details"><dl><dt>Calculated peak stress</dt><dd><span id="comparison-stress-{i}">{row['stress']:.1f}</span> MPa</dd><dt>Calculated deck drop</dt><dd><span id="comparison-drop-{i}">{row['drop']:.2f}</span> in</dd></dl><p id="comparison-shore-{i}">{f"{row['shore']:,.0f} lbf into one shore" if i<2 else 'No body reaction credited'}</p><p class="tradeoff">{tradeoff}</p><p class="card-note">{note}</p></div></article>''')

equipment_rows=''.join(f'<tr><td>{r["people"]}</td><td>{r["extraLbf"]:,}</td><td>{r["stress"]:.2f}</td><td>{r["drop"]:.3f}</td><td>{r["portalReaction"]:,.0f}</td><td>{escape(r["member"])}</td></tr>' for r in sorted(DATA['equipment'],key=lambda r:(r['people'],r['extraLbf'])))
old=(SITE/'iteration-05.html').read_text()
head=old[:old.index('<main>')]
head=head.replace('A shared structure, with access · Earl structural iteration 05','The truss, explained · Earl structural iteration 05a')
head=re.sub(r'<meta name="description"[^>]+>', '<meta name="description" content="Explore Earl’s accessible perimeter truss: crowd and gear controls, shored comparisons, material sizes and wall thicknesses, with the math underneath.">',head)
head=head.replace('href="https://baaabs.org/structural/iteration-05.html"','href="https://baaabs.org/structural/iteration-05a.html"').replace('href="iteration05.css?v=access-2"','href="iteration05a.css?v=1"').replace('src="iteration05.js"','src="iteration05a.js?v=1"')
body='''<main class="study05a">__TABS__
<p class="eyebrow">Iteration 05a · November 14, 2026 · Visual guide to the 05 calculations</p>
<h1>A truss. A clear cabin. Room for the stuff.</h1>
<p class="intro">The perimeter truss is our preferred direction for keeping the cabin clear and the space under the deck accessible. Explore what it carries, what it weighs, and where Earl could help.</p>
<div class="quick-facts"><span><strong>38 × 8 ft</strong> deck</span><span><strong>0</strong> cabin posts</span><span><strong>2</strong> permanent access openings</span><span><strong>20 people</strong> design target</span></div>
<p class="qualification"><strong>A promising concept, with engineering still to do.</strong> The colors below describe one calculated stress check. They do not establish a safe headcount. Chassis connections, buckling, dancing response and cabin protection remain unresolved.</p>
<p class="notes">This is a new presentation of iteration 05’s existing results. <a href="iteration-05.html">Read the original study</a> or <a href="#math05a">jump to the math</a>.</p>
<p id="data-error05a" role="alert" hidden></p><noscript><p class="qualification">JavaScript is required for the controls. Default values and the calculation tables remain readable below.</p></noscript>

<section class="study-panel" aria-labelledby="explore-title"><p class="section-kicker">01 / Try a calculated case</p><h2 id="explore-title">People up top. Little totes underneath.</h2><p class="panel-intro">All cases include the full 2,311 lb allowance for sheep skins and mounts. Choose one of the three crowd sizes actually calculated.</p>
<div class="explorer-grid"><div><form id="concept-controls"><fieldset data-needs-data disabled><legend class="sr-only">Accessible truss load controls</legend><div class="control"><label for="crowd05a">People on the deck <output id="crowd-value" for="crowd05a">20</output></label><input id="crowd05a" type="range" min="0" max="2" step="1" value="2" aria-valuetext="20 people"><div class="scale"><span>8 people</span><span>12 people</span><span>20 people</span></div></div><label for="gear05a">Controllers, cables and totes</label><select id="gear05a"><option value="0">0 lb · empty service space</option><option value="250" selected>250 lb · planning allowance</option><option value="500">500 lb · heavier test case</option><option value="1000">1,000 lb · heavier test case</option></select></fieldset></form><figure class="crowd-display"><svg viewBox="0 0 360 100" role="img" aria-label="Illustration of the selected number of people"><g id="crowd-icons"></g></svg><figcaption id="crowd-caption">20 people illustrated; placement is not the governing load case.</figcaption></figure><p class="notes">The 250 lb allowance is a placeholder for light service gear. The 500 and 1,000 lb settings test sensitivity; they are not storage ratings.</p></div>
<div class="selected-result yellow" id="selected-result"><div class="percent-number" id="stress-use">92%</div><p class="result-label">of our chosen stress limit used</p><p id="stress-label">Near the chosen limit</p><div class="meter" aria-hidden="true"><span id="stress-fill" style="width:61.2%"></span></div><div class="meter-labels"><span>0</span><span>White line = 100% limit</span><span>150%</span></div><p class="result-label"><span id="stress-demand">190.0</span> MPa demand / 207 MPa limit</p><dl class="metric-pair"><div><dt>Calculated deck drop</dt><dd><span id="deck-drop">0.68</span> <small>in</small></dd></div><div><dt>Peak force at one chassis seat</dt><dd><span id="seat-load">8,360</span> <small>lbf</small></dd></div></dl><p class="live-summary" id="selection-summary" aria-live="polite">20 people + 250 lb of service gear. Stress screen only; no operating headcount established.</p></div></div>
<div class="model-wrap"><model-viewer id="model05a" data-shore-variant="end-truss" data-rear-frame-src="../assets/models/earl-roof-attachment-study.glb?v=temple-ears-1" camera-controls camera-orbit="-125deg 76deg 16m" camera-target="-.73m 3m 0m" exposure="1.25" shadow-intensity="0" alt="Current accessible perimeter truss on Earl, with a permanent opening on each side and no cabin posts"></model-viewer></div>
<div class="model-toolbar"><label><input id="skin05a" type="checkbox">Show sheep skin and deck</label><a href="../the_build.html">Open the full panel workshop</a></div><p id="rear-frame-status" class="notes">Drag to orbit the current 05 concept. This is undeformed geometry; it does not animate calculated movement. Teal members show the analytical framing, not fabricated joints.</p>
<div class="access-note"><strong>Reach the gear without taking out a brace.</strong><p>One permanent opening on each side: about <strong>50.5 × 25.5 in</strong>. Reserve a <strong>24 in</strong> central service strip. Local height above the raised ties is about <strong>22.6 in</strong>; real roof shape, loaded clearances, trays and access panels still need measurement and design.</p></div></section>

<section aria-labelledby="compare-title"><p class="section-kicker">02 / Compare the tradeoffs</p><h2 id="compare-title">Best for the brief. Heavier on the scale.</h2><p>These three concepts use the crowd control above: <strong><span id="comparison-crowd">20</span> people</strong>. For a common basis, each comparison includes full skins, <strong>zero added service gear</strong>, and the same 2× people-force assumption.</p><div class="legend"><span class="green">● More room below the stress limit</span><span class="yellow">▲ Near the limit</span><span class="red">■ Above the limit</span></div><div class="comparison-grid">__CARDS__</div><p class="recommendation05a"><strong>Why favor the accessible truss?</strong> It combines the deck and potential skin supports while preserving permanent access, with no credited load path through Earl’s body. It adds about <strong>969 lb</strong> versus 04 and puts more demand on the end connections. That is a fit to our priorities, not proof of a universal optimum.</p><p class="notes">All three keep added posts out of the cabin in these models. These are different frames, depths and portal sizes. The differences are not the isolated effect of adding or removing shores. No maximum headcount was calculated for the final accessible truss.</p></section>

<section class="study-panel" aria-labelledby="shore-title"><p class="section-kicker">03 / Follow the load</p><h2 id="shore-title">Can the truss be shored to Thomas?</h2><p><strong>Conceptually, yes.</strong> Shores can provide additional paths into verified body structure and onward to the chassis. Earl’s actual landing members, connections and stiffness have to establish how much help is available.</p><div class="path-grid"><figure><svg id="load-path" viewBox="0 0 760 350" role="img" aria-label="Schematic of the chosen structural load path"></svg><figcaption id="path-caption">Current accessible truss: the two end portals carry the load. Schematic only.</figcaption></figure><div><label for="path05a">Compare the load paths</label><select id="path05a" data-needs-data disabled><option value="end">Current accessible truss · end supports</option><option value="body">Earlier light truss · six body shores</option></select><p id="path-finding">Adding shores to the exact accessible truss has not been calculated.</p><p class="notes">Side view: the shored drawing shows three of six shores. Dashed orange lines indicate assumed body-to-chassis load paths, not surveyed structural members. The 3D model above always shows the current accessible truss.</p></div></div><p>Place future shores at engineered truss nodes and verified body landings, preserving the access bays. Thin roof sheet alone is not the modeled load path. The <a href="https://thomasbuiltbuses.com/content/uploads/2020/06/brochure-hdx-school-summer-2020.pdf">newer HDX construction brochure</a> shows body and chassis architecture; it supplies no added-deck capacity for our 2007 bus.</p></section>

<section class="study-panel" aria-labelledby="sensitivity-title"><p class="section-kicker">04 / Understand the limit</p><h2 id="sensitivity-title">What does “fails the check” mean?</h2><p>Keep the current truss, <strong>20 people and 250 lb of gear</strong> fixed. Change one assumption and see what the calculation says.</p><div class="sensitivity-grid"><div><label for="sensitivity05a">Assumption to inspect</label><select id="sensitivity05a" data-needs-data disabled><option value="base">2× people force · feet held against rotation</option><option value="3x-250">3× people force · same feet</option><option value="pinned-250">2× people force · feet free to rotate</option></select><p id="sensitivity-explanation">Doubling dancer weight is a chosen load sensitivity, not a validated bound on dancing forces.</p><p class="plain-warning">2× and 3× are force assumptions. They do not mean “ordinary dancing” and “jumping in unison.” Resonance, damping and actual movement have not been solved here.</p></div><div class="sensitivity-result yellow" id="sensitivity-result"><strong id="sensitivity-stress">190.0 MPa</strong><p id="sensitivity-status" aria-live="polite">Near the chosen limit · 92% of the 207 MPa screen</p><div class="meter" aria-hidden="true"><span id="sensitivity-fill"></span></div><div class="meter-labels"><span>0</span><span>White line = 207 MPa</span><span>310.5 MPa</span></div><dl class="metric-pair"><div><dt>Applied people force</dt><dd id="sensitivity-force">9,000 lbf</dd></div><div><dt>Calculated deck drop</dt><dd id="sensitivity-drop">0.68 in</dd></div><div><dt>Peak seat compression / uplift</dt><dd id="sensitivity-seat">8,360 / 0 lbf</dd></div></dl></div></div></section>

<section aria-labelledby="steel-title"><p class="section-kicker">05 / Know the material</p><h2 id="steel-title">Steel tube—with the wall spelled out.</h2><p>The concept basis is <strong>ASTM A500 Grade C carbon-steel hollow structural sections (HSS)</strong>. This makes the existing <strong>345 MPa (about 50 ksi)</strong> assumed yield strength explicit. Grade, availability and the final member schedule still require verification before procurement.</p><div class="material-summary"><span><strong>⅛ in</strong> most roof members</span><span><strong>3/16 in</strong> lower chords</span><span><strong>¼ in</strong> main end posts and sills</span></div><p>In “6 × 2 × ⅛,” the first two numbers are outside tube dimensions; the last is the <strong>nominal wall thickness</strong>. The size alone does not describe the wall.</p><div class="table-wrap"><table><caption class="sr-only">Current accessible-truss conceptual member schedule</caption><thead><tr><th scope="col">Member</th><th scope="col">Outside dimensions</th><th scope="col">Nominal wall</th><th scope="col">Orientation / status</th></tr></thead><tbody>__MATERIALS__</tbody></table></div><p class="qualification"><strong>Some inherited members still use model dimensions rather than a selected stock size.</strong> The 45, 65, 38 and approximately 52 mm members above remain explicitly unresolved. Do not silently round them to nearby stock or use this table as a fabrication BOM.</p><p><strong>Other material assumptions:</strong> ¾ in plywood at 600 kg/m³ is included as floor weight only; its grade, span capacity and fastenings are unselected. The 206 nonstructural skins use a provisional 20-gauge perforated carbon-steel estimate: about 0.0359 in sheet thickness, approximately 40% open area, 1,849 lb bare plus a 25% mounting allowance. No stiffness or strength is credited to the plywood or decorative skin.</p><p class="notes">The steel model uses E = 200 GPa and density 7,850 kg/m³. It distinguishes nominal wall from the reduced design wall: t = 0.93tₙₒₘ. Catalog section properties are used where available; other shapes use the documented idealization. <a href="https://steeltubeinstitute.org/resources/astm-a500/">Steel Tube Institute: A500 strength and design-wall basis</a> · <a href="iteration-05a-materials.json">Exact member-to-material mapping</a>.</p></section>

<section id="math05a" class="technical-divider" aria-labelledby="math-title"><p class="eyebrow">The math underneath</p><h2 id="math-title">Same calculations. Visible assumptions.</h2><p>05a reads the original <a href="iteration-05-data.json">iteration 05 dataset</a>. Controls select directly solved rows. They do not interpolate between crowds, extrapolate a capacity, or run a dynamic simulation.</p>
<h3>1. Assemble the load</h3><div class="equations"><math display="block"><mrow><mi mathvariant="bold">f</mi><mo>=</mo><msub><mi mathvariant="bold">f</mi><mtext>frame+floor</mtext></msub><mo>+</mo><msub><mi mathvariant="bold">f</mi><mtext>skins</mtext></msub><mo>+</mo><msub><mi mathvariant="bold">f</mi><mtext>gear</mtext></msub><mo>+</mo><mi>α</mi><mi>n</mi><mo>(</mo><mn>225</mn><mtext> lbf</mtext><mo>)</mo><mi mathvariant="bold">q</mi><mo>(</mo><mi>n</mi><mo>)</mo></mrow></math><p>n is the selected number of people. q(n) distributes their total force over each tested crowd footprint. α = 2 for the main controls, or 3 in the heavier sensitivity case.</p><p class="math-working" id="load-working">4,493.35 + 2,311.25 + 250 + 2 × 20 × 225 = 16,054.60 lbf</p><p id="mass-working">11,555 lb physically carried in this model; the force multiplier adds no physical mass.</p></div><p>Dead loads remain unmultiplied. The model excludes unweighed guards, stairs, sound equipment, connection hardware and reinforcement. Skin and gear are distributed along the edge girders in balanced, all-driver-side and all-passenger-side cases; actual brackets and tote trays need local checks.</p>
<h3>2. Solve the idealized frame</h3><div class="equations"><math display="block"><mrow><mi mathvariant="bold">K</mi><mi mathvariant="bold">u</mi><mo>=</mo><mi mathvariant="bold">f</mi></mrow></math><p>K contains the member stiffnesses and assumed restraints; u contains displacement and rotation. The 3D Euler–Bernoulli beam model assumes rigid member joints and fixed chassis seats in the main case. It credits no body springs in the accessible truss.</p><p>The earlier shored comparison assumes six independent compression-only paths, each k = 5,000 lbf/in. Their real stiffness and capacity are unknown. The pinned sensitivity releases foot rotation.</p></div>
<h3>3. Compare the normal-stress envelope with the chosen ceiling</h3><div class="equations"><math display="block"><mrow><msub><mi>σ</mi><mi>e</mi></msub><mo>=</mo><mfrac><mrow><mo>|</mo><msub><mi>N</mi><mi>a</mi></msub><mo>|</mo></mrow><mi>A</mi></mfrac><mo>+</mo><mfrac><mrow><mo>|</mo><msub><mi>M</mi><mi>y</mi></msub><mo>|</mo><mi>h</mi></mrow><mrow><mn>2</mn><msub><mi>I</mi><mi>y</mi></msub></mrow></mfrac><mo>+</mo><mfrac><mrow><mo>|</mo><msub><mi>M</mi><mi>z</mi></msub><mo>|</mo><mi>b</mi></mrow><mrow><mn>2</mn><msub><mi>I</mi><mi>z</mi></msub></mrow></mfrac></mrow></math><p>Axial force Nₐ and bending moments Mᵧ, M𝓏 act on section area A and second moments Iᵧ, I𝓏. The section dimensions are b and h. The reported result is the largest sampled value across the tested placements.</p><math display="block"><mrow><msub><mi>σ</mi><mtext>screen</mtext></msub><mo>=</mo><mn>0.60</mn><msub><mi>F</mi><mi>y</mi></msub><mo>=</mo><mn>0.60</mn><mo>×</mo><mn>345</mn><mo>=</mo><mn>207</mn><mtext> MPa</mtext></mrow></math><p>Display percentage = 100 × σₘₐₓ / 207. Green: ≤80%; yellow: &gt;80% through 100%; red: &gt;100%. These are stress-screen colors, not probabilities of safety or a whole-vehicle factor of safety.</p></div><p><strong>Currently selected governing stress member / placement:</strong> <span id="governing05a">Truss vertical driver 4 · patch_12ft_at_8ft|panels_driver</span>.</p><p>The tested patterns include full-deck, half-deck and side groups plus longitudinally swept crowd footprints. Stress, drop and support-force peaks may come from different placements. Buckling, full combined-force strength, connection/local-wall failure, fatigue and vehicle loads are outside this check.</p>
<h3>4. Directly solved accessible-truss cases</h3><p>Full skin allowance, fixed chassis seats, α = 2. “Drop” is the maximum sampled downward deck movement under that amplified load; no floor-motion acceptance criterion has been applied.</p><div class="table-wrap"><table><thead><tr><th>People</th><th>Gear lb</th><th>Stress MPa</th><th>Drop in</th><th>Peak seat lbf</th><th>Governing stress member</th></tr></thead><tbody>__CASES__</tbody></table></div>
<h3>5. What a dynamic assessment still has to solve</h3><div class="equations"><math display="block"><mrow><mi mathvariant="bold">M</mi><mover><mi mathvariant="bold">u</mi><mo>¨</mo></mover><mo>+</mo><mi mathvariant="bold">C</mi><mover><mi mathvariant="bold">u</mi><mo>˙</mo></mover><mo>+</mo><mi mathvariant="bold">K</mi><mi mathvariant="bold">u</mi><mo>=</mo><mi mathvariant="bold">f</mi><mo>(</mo><mi>t</mi><mo>)</mo></mrow></math><p>This time-dependent equation is <strong>not solved in iteration 05</strong>. Mass M, damping C, natural frequencies and time-varying crowd forces matter. A “no synchronized jumping” rule cannot be derived from the 2× and 3× static-force comparisons.</p></div><p><a href="https://www.aisc.org/globalassets/aisc/publications/facts-for-steel-buildings-5-vibrations.pdf">AISC’s vibration guidance</a> explains resonance and distinguishes vibration serviceability from strength and fatigue.</p>
<h3>6. Verification, limitations and source</h3><p>The underlying 05 work replays the inherited element, bearing, equilibrium and iteration-04 boundary checks. A finer beam subdivision reproduced the selected 20-person / 250 lb case at 190.03 MPa and 0.680 in. These verify the calculation implementation; they do not verify Earl’s real connections or establish occupancy.</p><p>The model keeps the 38 × 8 ft deck and existing sheep geometry. Survey the roof, portals, rear drop-frame, engine access and actual body members. Resolve material stock sizes, welds, bolts, buckling, dynamic behavior, axle loads, stability and the retained 102-inch road envelope before a reviewed fabrication release.</p><div class="download-links"><a href="../assets/downloads/structural/iteration-05-source.zip" download>Download calculation source</a><a href="iteration-05-data.json">Original 05 data</a><a href="iteration-05a-materials.json">Material mapping</a><a href="../assets/structural-models-05.json">Model geometry</a><a href="iteration-05.html">Full 05 study and release tracker</a></div><p class="notes">November 14, 2026 (Pacific) · 05a adds the visual explanation, body-shoring distinction and explicit material schedule. It makes no change to the calculated design or its release status.</p></section></main></body></html>
'''
body=body.replace('__TABS__',tabs('iteration-05a.html')).replace('__CARDS__',''.join(cards)).replace('__MATERIALS__',schedule_rows).replace('__CASES__',equipment_rows)
(SITE/'iteration-05a.html').write_text(head+body)
for name,_ in TABS:
    if name=='iteration-05a.html': continue
    p=SITE/name
    p.write_text(re.sub(r'<nav class="design-tabs".*?</nav>',tabs(name),p.read_text(),count=1,flags=re.S))
print('Built 05a and material mapping; linked all seven structural tabs.')
